import * as THREE from 'three';import {poseMoaPlaymate} from '../residents/moa-playmate.js';import {poseResident} from '../residents/residents.js';import {SEAT_CONTACT} from '../world/seating.js';
export function posePlazaVisitor(model,r,reduced){const t=reduced?0:r.distance/.34*Math.PI*2/5,key=[r.pose,r.moving&&!reduced?t:0,reduced].join(':');if(model.userData.plazaPoseKey!==key){model.userData.plazaPoseKey=key;if(r.id==='moa-playmate'){poseMoaPlaymate(model,{seated:r.pose,walking:r.moving,time:t,reducedMotion:reduced});model.userData.plazaSeatContact=.145;}else{poseResident(model,{walking:r.moving,time:t,showBook:false});for(const [role,part]of Object.entries(model.userData.parts??{})){const rest=model.userData.restPose?.[role];if(!rest)continue;if(role.startsWith('Foot')){part.position.x+=(rest.position.x-part.position.x)*r.pose;part.position.z+=(rest.position.z+.12-part.position.z)*r.pose;part.position.y+=(rest.position.y+.06-part.position.y)*r.pose;part.rotation.x+=(rest.rotation.x-.20-part.rotation.x)*r.pose;}if(role==='Arm.L'||role==='Arm.R'){part.rotation.copy(rest.rotation);part.rotation.x-=(role==='Arm.L'?.32:.48)*r.pose;}}if(model.userData.plazaSeatContact===undefined){model.updateWorldMatrix(true,true);const body=model.userData.parts?.Body??model;model.userData.plazaSeatContact=new THREE.Box3().setFromObject(body).min.y-model.getWorldPosition(new THREE.Vector3()).y;}}
 }model.position.set(r.x,r.y+(SEAT_CONTACT-model.userData.plazaSeatContact)*r.pose,r.z);model.rotation.set(0,r.yaw,0);}
